/// An original passenger transaction advances the account but does not change equipment fit.
pub(crate) fn prepare_passage_action(&self, delivered: bool) -> Result<Self, Error> {
    let mut data = self.data;
    data.revision = data
        .revision
        .checked_add(1)
        .ok_or(Error::SequenceExhausted)?;
    if delivered {
        data.credits = data
            .credits
            .checked_add(crate::flight::PASSAGE_REWARD_TENTHS)
            .ok_or(Error::CreditOverflow)?;
    }
    Ok(Self { data })

}

/// Bind a retained passenger reception to the actual system travelled to before its berth.
pub(crate) fn validate_passenger_berth(
    &self,
    dock: DockContext,
    tick: u64,
) -> Result<(), SaveError> {
    self.spent_at(dock, tick)?;
    let count = usize::try_from(dock.visit().checked_sub(dock.sequence()).ok_or(INVALID)?)
        .map_err(|_| INVALID)?;
    let system = if count == 0 {
        SystemId::AVENOR
    } else {
        self.legs.get(count - 1).ok_or(INVALID)?.destination
    };
    if dock.system() != system {
        return Err(INVALID);
    }
    Ok(())
